	CBNZ R3, ci_general_bank_slow
	MOVD ACI_CALLEE_NUM_GENERAL(R2), R5
	CBZ  R5, ci_general_bank_slow
	MOVD CTX_ARENA_GEN_IDX(R19), R4
	ADD  R5, R4, R6
	MOVD CTX_ARENA_GENERAL_SLAB_CAP(R19), R7
	CMP  R7, R6
	BGT  ci_general_bank_slow
	MOVD ACI_NUM_GENERAL_ARGS(R2), R7
	MOVD CTX_GENERALS_BASE(R19), R10
	MOVD $24, R12
	CBZ  R7, ci_general_bank_alloc
	MOVD $0, R8
ci_general_bank_check_loop:
	LSL  $3, R8, R3
	ADD  $ACI_GENERAL_ARG_SRCS, R3, R11
	ADD  R2, R11, R11
	MOVD (R11), R3
	MUL  R12, R3, R3
	ADD  R10, R3, R11
	MOVD 0(R11), R3
	CBZ  R3, ci_general_bank_check_next
	MOVD 16(R11), R3
	AND  $0x1F, R3, R3
	CMP  $25, R3
	BEQ  ci_general_bank_slow
	CMP  $17, R3
	BEQ  ci_general_bank_slow
ci_general_bank_check_next:
	ADD  $1, R8, R8
	CMP  R7, R8
	BLT  ci_general_bank_check_loop
ci_general_bank_alloc:
	MUL  R12, R4, R4
	MOVD CTX_ARENA_GENERAL_SLAB(R19), R3
	ADD  R3, R4, R4
	MOVD R4, CF_REGS_GENERAL_PTR(R9)
	MOVD R5, CF_REGS_GENERAL_LEN(R9)
	MOVD R5, CF_REGS_GENERAL_CAP(R9)
	MOVD $1, R3
	MOVB R3, CF_HAS_GENERAL_ALLOC(R9)
	MOVD R6, CTX_ARENA_GEN_IDX(R19)
	MOVB R3, CTX_ARENA_BANKS_DIRTY(R19)
	CBZ  R7, ci_general_bank_save
	MOVD $0, R8
ci_general_bank_copy_loop:
	LSL  $3, R8, R3
	ADD  $ACI_GENERAL_ARG_SRCS, R3, R11
	ADD  R2, R11, R11
	MOVD (R11), R3
	MUL  R12, R3, R3
	ADD  R10, R3, R11
	MUL  R12, R8, R13
	ADD  R4, R13, R13
	MOVD 0(R11), R3
	MOVD R3, 0(R13)
	MOVD 8(R11), R3
	MOVD R3, 8(R13)
	MOVD 16(R11), R3
	MOVD R3, 16(R13)
	ADD  $1, R8, R8
	CMP  R7, R8
	BLT  ci_general_bank_copy_loop
ci_general_bank_save:
	MOVD CTX_DISPATCH_SAVES(R19), R3
	MOVD CTX_FRAME_POINTER(R19), R11
	LSL  $DS_SIZE_SHIFT, R11, R11
	ADD  R11, R3, R3
	MOVD ACI_CALLEE_BODY(R2), R11
	MOVD R11, DS_CODE_BASE(R3)
	MOVD ACI_CALLEE_BODY_LEN(R2), R11
	MOVD R11, DS_CODE_LEN(R3)
	MOVD ACI_CALLEE_INT_CONSTS(R2), R11
	MOVD R11, DS_INT_CONSTS(R3)
	MOVD ACI_CALLEE_FLT_CONSTS(R2), R11
	MOVD R11, DS_FLOAT_CONSTS(R3)
	MOVD ACI_CALLEE_STR_CONSTS(R2), R11
	MOVD R11, DS_STRING_CONSTS(R3)
	MOVD ACI_CALLEE_BOOL_CONSTS(R2), R11
	MOVD R11, DS_BOOL_CONSTS(R3)
	MOVD ACI_CALLEE_UINT_CONSTS(R2), R11
	MOVD R11, DS_UINT_CONSTS(R3)
	B    ci_no_general_bank
ci_general_bank_slow:
	BL   ·handlerCallInlineSetupGeneralBank(SB)
	MOVD CTX_FRAME_POINTER(R19), R3
	MOVD $CALLFRAME_SIZE, R4
	MUL  R3, R4, R4
	MOVD CTX_CSTACK_BASE(R19), R9
	ADD  R4, R9, R9
ci_no_general_bank:

	MOVD CTX_ASM_CI_PTRS(R19), R7
	MOVD CTX_FRAME_POINTER(R19), R5
	MOVBU CTX_CI_BASES_ROOT_MATCH(R19), R6
	CBZ  R6, ci_callee_own_call_info
	MOVD CTX_CI_BASES_BY_FUNC(R19), R8
	MOVD ACI_CALLEE_FUNC_INDEX(R2), R6
	MOVD (R8)(R6<<3), R8
	B    ci_callee_call_info_resolved

ci_callee_own_call_info:
	MOVD ACI_CALLEE_CALL_INFO(R2), R8

ci_callee_call_info_resolved:
	MOVD R8, (R7)(R5<<3)
	MOVD R8, CTX_ASM_CALL_INFO_BASE(R19)

	MOVD ACI_CALLEE_BODY(R2), R22
	MOVD ACI_CALLEE_BODY_LEN(R2), R21
	MOVD ACI_CALLEE_INT_CONSTS(R2), R26
	MOVD $0, R20
	MOVD CF_REGS_INTS_PTR(R9), R23
	MOVD CF_REGS_FLOATS_PTR(R9), R24

	MOVD R22, CTX_CODE_BASE(R19)
	MOVD R21, CTX_CODE_LEN(R19)
	MOVD R20, CTX_PC(R19)
	MOVD R23, CTX_INTS_BASE(R19)
	MOVD R24, CTX_FLOATS_BASE(R19)
	MOVD R26, CTX_INT_CONSTS_BASE(R19)
	MOVD ACI_CALLEE_FLT_CONSTS(R2), R7
	MOVD R7, CTX_FLT_CONSTS_BASE(R19)
	MOVD CF_REGS_STRINGS_PTR(R9), R7
	MOVD R7, CTX_STRINGS_BASE(R19)
	MOVD CF_REGS_UINTS_PTR(R9), R7
	MOVD R7, CTX_UINTS_BASE(R19)
	MOVD CF_REGS_BOOLS_PTR(R9), R7
	MOVD R7, CTX_BOOLS_BASE(R19)
	MOVD CF_REGS_GENERAL_PTR(R9), R7
	MOVD R7, CTX_GENERALS_BASE(R19)
	MOVD CF_REGS_SLICEBYTE_PTR(R9), R7
	MOVD R7, CTX_SLICES_BYTE_BASE(R19)
	MOVD ACI_CALLEE_STR_CONSTS(R2), R7
	MOVD R7, CTX_STR_CONSTS_BASE(R19)
	MOVD ACI_CALLEE_BOOL_CONSTS(R2), R7
	MOVD R7, CTX_BOOL_CONSTS_BASE(R19)
	MOVD ACI_CALLEE_UINT_CONSTS(R2), R7
	MOVD R7, CTX_UINT_CONSTS_BASE(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	DISPATCH_NEXT()

ci_fallback_post_fp_inc:
	MOVD CTX_FRAME_POINTER(R19), R7
	SUB  $1, R7, R7
	MOVD R7, CTX_FRAME_POINTER(R19)

ci_fallback:
	SUB  $2, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_TIER2, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	JMP  ·dispatchExit(SB)

ci_overflow:
	SUB  $2, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_CALL_OVERFLOW, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	JMP  ·dispatchExit(SB)

// handlerCallInlineSetupGeneralBank: trampoline for isFastPath==3 general-bank setup.
TEXT ·handlerCallInlineSetupGeneralBank(SB), NOSPLIT, $32-0
	NO_LOCAL_POINTERS
	MOVD R2, 32(RSP)
	MOVD R20, CTX_SAVED_PC(R19)
	MOVD R19, 8(RSP)
	MOVD R2, 16(RSP)
	BL   ·asmCallSetupGeneralBank(SB)
	MOVD 24(RSP), R19
	MOVD CTX_SAVED_PC(R19), R20
	MOVD CTX_CODE_BASE(R19), R22
	MOVD CTX_CODE_LEN(R19), R21
	MOVD CTX_INTS_BASE(R19), R23
	MOVD CTX_FLOATS_BASE(R19), R24
	MOVD CTX_INT_CONSTS_BASE(R19), R26
	MOVD CTX_JUMP_TABLE(R19), R25
	MOVD 32(RSP), R2
	RET

// handlerCallInlineClearGeneralBank: trampoline that clears the GC-visible general slab on return.
TEXT ·handlerCallInlineClearGeneralBank(SB), NOSPLIT, $24-0
	NO_LOCAL_POINTERS
	MOVD R20, CTX_SAVED_PC(R19)
	MOVD R19, 8(RSP)
	BL   ·asmReturnClearGeneralBank(SB)
	MOVD 16(RSP), R19
	MOVD CTX_SAVED_PC(R19), R20
	MOVD CTX_CODE_BASE(R19), R22
	MOVD CTX_CODE_LEN(R19), R21
	MOVD CTX_INTS_BASE(R19), R23
	MOVD CTX_FLOATS_BASE(R19), R24
	MOVD CTX_INT_CONSTS_BASE(R19), R26
	MOVD CTX_JUMP_TABLE(R19), R25
	RET

// handlerReturnInline handles OpReturn with ASM-inlined fast path.
TEXT ·handlerReturnInline(SB), NOSPLIT, $32-0
	NO_LOCAL_POINTERS
	MOVD CTX_FRAME_POINTER(R19), R4
	MOVD CTX_BASE_FRAME_POINTER(R19), R5
	CMP  R5, R4
	BLE  ri_fallback

	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R4, R7, R8
	ADD  R6, R8, R8

	MOVD CF_DEFERBASE(R8), R7
	MOVD CTX_DEFER_STACK_LEN(R19), R9
	CMP  R9, R7
	BNE  ri_fallback

	MOVD CF_SIMPLEDEFER(R8), R7
	CBZ  R7, ri_no_simple_defer
	MOVBU SDR_ACTIVE(R7), R9
	CBNZ R9, ri_fallback
ri_no_simple_defer:

	MOVBU CF_ROOT_SWAPPED(R8), R7
	CBNZ R7, ri_fallback
	MOVD CF_SHARED_CELLS(R8), R7
	CBNZ R7, ri_fallback

	LSRW $24, R0, R1
	AND  $0xFF, R1, R1

	SUB  $1, R4, R21
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22

	CBZ  R1, ri_no_retval
	CMP  $1, R1
	BNE  ri_multi

	MOVD CF_RETURNDEST_PTR(R8), R7
	CBZ  R7, ri_fallback

	MOVBU VL_IS_UPVALUE(R7), R1
	CBNZ R1, ri_fallback

	MOVBU VL_KIND(R7), R1
	MOVBU VL_REGISTER(R7), R7

	CMP  $0, R1
	BEQ  ri_check_int
	CMP  $1, R1
	BEQ  ri_check_float
	CMP  $2, R1
	BEQ  ri_check_string
	CMP  $4, R1
	BEQ  ri_check_bool
	CMP  $5, R1
	BEQ  ri_check_uint
	CMP  $3, R1
	BEQ  ri_check_general
	B    ri_fallback

ri_check_int:
	MOVD CF_REGS_INTS_LEN(R8), R1
	CBZ  R1, ri_fallback

ri_copy_int:
	MOVD CF_REGS_INTS_PTR(R8), R1
	MOVD (R1), R1
	MOVD CF_REGS_INTS_PTR(R22), R3
	MOVD R1, (R3)(R7<<3)
	B    ri_no_retval

ri_check_float:
	MOVD CF_REGS_FLOATS_LEN(R8), R1
	CBZ  R1, ri_fallback

ri_copy_float:
	MOVD CF_REGS_FLOATS_PTR(R8), R1
	MOVD (R1), R1
	MOVD CF_REGS_FLOATS_PTR(R22), R3
	MOVD R1, (R3)(R7<<3)
	B    ri_no_retval

ri_check_string:
	MOVD CF_REGS_STRINGS_LEN(R8), R1
	CBZ  R1, ri_fallback
	MOVD CF_REGS_STRINGS_PTR(R8), R1
	MOVD (R1), R3
	MOVD 8(R1), R1
	MOVD CF_REGS_STRINGS_PTR(R22), R5
	LSL  $4, R7, R6
	MOVD R3, (R5)(R6)
	ADD  $8, R6, R6
	MOVD R1, (R5)(R6)
	B    ri_no_retval

ri_check_bool:
	MOVD CF_REGS_BOOLS_LEN(R8), R1
	CBZ  R1, ri_fallback
	MOVD  CF_REGS_BOOLS_PTR(R8), R1
	MOVBU (R1), R1
	MOVD  CF_REGS_BOOLS_PTR(R22), R3
	MOVB  R1, (R3)(R7)
	B     ri_no_retval

ri_check_uint:
	MOVD CF_REGS_UINTS_LEN(R8), R1
	CBZ  R1, ri_fallback
	MOVD CF_REGS_UINTS_PTR(R8), R1
	MOVD (R1), R1
	MOVD CF_REGS_UINTS_PTR(R22), R3
	MOVD R1, (R3)(R7<<3)
	B    ri_no_retval

ri_check_general:
	MOVD $runtime·writeBarrier(SB), R1
	MOVBU (R1), R1
	CBNZ R1, ri_fallback
	MOVD CF_REGS_GENERAL_LEN(R8), R1
	CBZ  R1, ri_fallback
	MOVD CF_REGS_GENERAL_PTR(R8), R1
	MOVD CF_REGS_GENERAL_PTR(R22), R5
	MOVD $24, R6
	MUL  R6, R7, R6
	ADD  R6, R5, R5
	MOVD 0(R1), R3
	MOVD R3, 0(R5)
	MOVD 8(R1), R3
	MOVD R3, 8(R5)
	MOVD 16(R1), R3
	MOVD R3, 16(R5)
	B    ri_no_retval

ri_multi:
	CMP  $4, R1
	BGT  ri_fallback
	MOVD CF_FUNCTION(R8), R3
	MOVD FN_RESULT_KINDS_LEN(R3), R4
	CMP  R4, R1
	BGT  ri_fallback
	MOVD R1, CTX_RET_COUNT(R19)
	MOVD ZR, CTX_RET_INDEX(R19)
	MOVD ZR, (CTX_RET_CURSORS+0)(R19)
	MOVD ZR, (CTX_RET_CURSORS+8)(R19)
	MOVD ZR, (CTX_RET_CURSORS+16)(R19)
	MOVD ZR, (CTX_RET_CURSORS+24)(R19)
	MOVD ZR, (CTX_RET_CURSORS+32)(R19)
	MOVD ZR, (CTX_RET_CURSORS+40)(R19)

ri_multi_loop:
	MOVD CTX_RET_INDEX(R19), R5
	MOVD CTX_RET_COUNT(R19), R6
	CMP  R6, R5
	BGE  ri_no_retval
	MOVD CF_RETURNDEST_LEN(R8), R6
	CMP  R6, R5
	BGE  ri_no_retval
	MOVD $VL_SIZE, R6
	MUL  R5, R6, R7
	MOVD CF_RETURNDEST_PTR(R8), R6
	ADD  R6, R7, R7
	MOVBU VL_IS_UPVALUE(R7), R1
	CBNZ R1, ri_fallback
	MOVBU VL_KIND(R7), R1
	MOVD CF_FUNCTION(R8), R3
	MOVD FN_RESULT_KINDS(R3), R3
	MOVBU (R3)(R5), R3
	CMP  R3, R1
	BNE  ri_fallback
	MOVBU VL_REGISTER(R7), R7
	ADD  $CTX_RET_CURSORS, R19, R4
	MOVD (R4)(R1<<3), R3
	ADD  $1, R3, R6
	MOVD R6, (R4)(R1<<3)

	CMP  $0, R1
	BEQ  ri_multi_int
	CMP  $1, R1
	BEQ  ri_multi_float
	CMP  $2, R1
	BEQ  ri_multi_string
	CMP  $4, R1
	BEQ  ri_multi_bool
	CMP  $5, R1
	BEQ  ri_multi_uint
	B    ri_fallback

ri_multi_int:
	MOVD CF_REGS_INTS_LEN(R8), R6
	CMP  R6, R3
	BGE  ri_fallback
	MOVD CF_REGS_INTS_PTR(R8), R1
	MOVD (R1)(R3<<3), R1
	MOVD CF_REGS_INTS_PTR(R22), R6
	MOVD R1, (R6)(R7<<3)
	B    ri_multi_next

ri_multi_float:
	MOVD CF_REGS_FLOATS_LEN(R8), R6
	CMP  R6, R3
	BGE  ri_fallback
	MOVD CF_REGS_FLOATS_PTR(R8), R1
	MOVD (R1)(R3<<3), R1
	MOVD CF_REGS_FLOATS_PTR(R22), R6
	MOVD R1, (R6)(R7<<3)
	B    ri_multi_next

ri_multi_uint:
	MOVD CF_REGS_UINTS_LEN(R8), R6
	CMP  R6, R3
	BGE  ri_fallback
	MOVD CF_REGS_UINTS_PTR(R8), R1
	MOVD (R1)(R3<<3), R1
	MOVD CF_REGS_UINTS_PTR(R22), R6
	MOVD R1, (R6)(R7<<3)
	B    ri_multi_next

ri_multi_string:
	MOVD CF_REGS_STRINGS_LEN(R8), R6
	CMP  R6, R3
	BGE  ri_fallback
	MOVD CF_REGS_STRINGS_PTR(R8), R1
	LSL  $4, R3, R3
	ADD  R3, R1, R1
	MOVD (R1), R4
	MOVD 8(R1), R1
	MOVD CF_REGS_STRINGS_PTR(R22), R6
	LSL  $4, R7, R7
	ADD  R7, R6, R6
	MOVD R4, (R6)
	MOVD R1, 8(R6)
	B    ri_multi_next

ri_multi_bool:
	MOVD CF_REGS_BOOLS_LEN(R8), R6
	CMP  R6, R3
	BGE  ri_fallback
	MOVD CF_REGS_BOOLS_PTR(R8), R1
	MOVBU (R1)(R3), R1
	MOVD CF_REGS_BOOLS_PTR(R22), R6
	MOVB R1, (R6)(R7)

ri_multi_next:
	MOVD CTX_RET_INDEX(R19), R5
	ADD  $1, R5, R5
	MOVD R5, CTX_RET_INDEX(R19)
	B    ri_multi_loop

ri_no_retval:
	MOVD CTX_ARENA_STR_IDX(R19), R3
	MOVD (CF_ARENA_SAVE+16)(R8), R5
	CMP  R3, R5
	BGE  ri_str_clear_done
	MOVD CTX_ARENA_STR_SLAB(R19), R6
	LSL  $4, R5, R1
	ADD  R1, R6, R1
	LSL  $4, R3, R3
	ADD  R6, R3, R3

ri_str_clear_loop:
	MOVD ZR, (R1)
	MOVD ZR, 8(R1)
	ADD  $16, R1, R1
	CMP  R3, R1
	BLT  ri_str_clear_loop

ri_str_clear_done:
	MOVD (CF_ARENA_SAVE+0)(R8), R1
	MOVD R1, CTX_ARENA_INT_IDX(R19)
	MOVD (CF_ARENA_SAVE+8)(R8), R1
	MOVD R1, CTX_ARENA_FLT_IDX(R19)
	MOVD (CF_ARENA_SAVE+16)(R8), R1
	MOVD R1, CTX_ARENA_STR_IDX(R19)
	MOVD (CF_ARENA_SAVE+32)(R8), R1
	MOVD R1, CTX_ARENA_BOOL_IDX(R19)
	MOVD (CF_ARENA_SAVE+40)(R8), R1
	MOVD R1, CTX_ARENA_UINT_IDX(R19)
	MOVD (CF_ARENA_SAVE+96)(R8), R1
	MOVD R1, CTX_ARENA_SLICEBYTE_IDX(R19)
	MOVD $1, R1
	MOVB R1, CTX_ARENA_BANKS_DIRTY(R19)

	MOVBU CF_HAS_GENERAL_ALLOC(R8), R3
	CBZ  R3, ri_gen_clear_done
	MOVD $runtime·writeBarrier(SB), R3
	MOVBU (R3), R3
	CBNZ R3, ri_gen_clear_slow
	MOVD CF_ARENA_SAVE_GENERAL_IDX(R8), R3
	MOVD CTX_ARENA_GEN_IDX(R19), R6
	SUB  R3, R6, R6
	CMP  $0, R6
	BLE  ri_gen_clear_restore
	MOVD $24, R9
	MUL  R3, R9, R9
	MOVD CTX_ARENA_GENERAL_SLAB(R19), R7
	ADD  R9, R7, R7
ri_gen_clear_zero:
	MOVD ZR, (R7)
	MOVD ZR, 8(R7)
	MOVD ZR, 16(R7)
	ADD  $24, R7, R7
	SUB  $1, R6, R6
	CBNZ R6, ri_gen_clear_zero
ri_gen_clear_restore:
	MOVD R3, CTX_ARENA_GEN_IDX(R19)
	MOVD $1, R6
	MOVB R6, CTX_ARENA_BANKS_DIRTY(R19)
	B    ri_gen_clear_done
ri_gen_clear_slow:
	BL   ·handlerCallInlineClearGeneralBank(SB)
	MOVD CTX_FRAME_POINTER(R19), R3
	SUB  $1, R3, R21
	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22
ri_gen_clear_done:

	MOVD R21, CTX_FRAME_POINTER(R19)
	MOVD R22, CTX_CURRENT_FRAME(R19)

	MOVD CTX_ASM_CI_PTRS(R19), R1
	MOVD (R1)(R21<<3), R1
	MOVD R1, CTX_ASM_CALL_INFO_BASE(R19)

	MOVD CF_PROGRAM_COUNTER(R22), R20
	MOVD CF_REGS_INTS_PTR(R22), R23
	MOVD CF_REGS_FLOATS_PTR(R22), R24

	MOVD CF_REGS_STRINGS_PTR(R22), R1
	MOVD R1, CTX_STRINGS_BASE(R19)
	MOVD CF_REGS_UINTS_PTR(R22), R1
	MOVD R1, CTX_UINTS_BASE(R19)
	MOVD CF_REGS_BOOLS_PTR(R22), R1
	MOVD R1, CTX_BOOLS_BASE(R19)
	MOVD CF_REGS_GENERAL_PTR(R22), R1
	MOVD R1, CTX_GENERALS_BASE(R19)
	MOVD CF_REGS_SLICEBYTE_PTR(R22), R1
	MOVD R1, CTX_SLICES_BYTE_BASE(R19)
	MOVD CF_REGS_SLICESINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_INT_BASE(R19)
	MOVD CF_REGS_SLICESFLOAT_PTR(R22), R1
	MOVD R1, CTX_SLICES_FLOAT_BASE(R19)
	MOVD CF_REGS_SLICESSTRING_PTR(R22), R1
	MOVD R1, CTX_SLICES_STRING_BASE(R19)
	MOVD CF_REGS_SLICESBOOL_PTR(R22), R1
	MOVD R1, CTX_SLICES_BOOL_BASE(R19)
	MOVD CF_REGS_SLICESUINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_UINT_BASE(R19)
	MOVD CF_REGS_COMPLEX_PTR(R22), R1
	MOVD R1, CTX_COMPLEX_BASE(R19)

	MOVD CTX_DISPATCH_SAVES(R19), R1
	LSL  $DS_SIZE_SHIFT, R21, R7
	ADD  R1, R7, R1
	MOVD DS_CODE_BASE(R1), R22
	MOVD DS_CODE_LEN(R1), R21
	MOVD DS_INT_CONSTS(R1), R26
	MOVD DS_FLOAT_CONSTS(R1), R7
	MOVD R7, CTX_FLT_CONSTS_BASE(R19)
	MOVD DS_STRING_CONSTS(R1), R7
	MOVD R7, CTX_STR_CONSTS_BASE(R19)
	MOVD DS_BOOL_CONSTS(R1), R7
	MOVD R7, CTX_BOOL_CONSTS_BASE(R19)
	MOVD DS_UINT_CONSTS(R1), R7
	MOVD R7, CTX_UINT_CONSTS_BASE(R19)

	MOVD R22, CTX_CODE_BASE(R19)
	MOVD R21, CTX_CODE_LEN(R19)
	MOVD R20, CTX_PC(R19)
	MOVD R23, CTX_INTS_BASE(R19)
	MOVD R24, CTX_FLOATS_BASE(R19)
	MOVD R26, CTX_INT_CONSTS_BASE(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	DISPATCH_NEXT()

ri_fallback:
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_RETURN, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	JMP  ·dispatchExit(SB)

// handlerReturnVoidInline handles OpReturnVoid with ASM-inlined fast path.
TEXT ·handlerReturnVoidInline(SB), NOSPLIT, $32-0
	NO_LOCAL_POINTERS
	MOVD CTX_FRAME_POINTER(R19), R4
	MOVD CTX_BASE_FRAME_POINTER(R19), R5
	CMP  R5, R4
	BLE  rvi_fallback

	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R4, R7, R8
	ADD  R6, R8, R8

	MOVD CF_DEFERBASE(R8), R7
	MOVD CTX_DEFER_STACK_LEN(R19), R9
	CMP  R9, R7
	BNE  rvi_fallback

	MOVD CF_SIMPLEDEFER(R8), R7
	CBZ  R7, rvi_no_simple_defer
	MOVBU SDR_ACTIVE(R7), R9
	CBNZ R9, rvi_fallback
rvi_no_simple_defer:

	MOVBU CF_ROOT_SWAPPED(R8), R7
	CBNZ R7, rvi_fallback
	MOVD CF_SHARED_CELLS(R8), R7
	CBNZ R7, rvi_fallback

	SUB  $1, R4, R21
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22

	MOVD CTX_ARENA_STR_IDX(R19), R3
	MOVD (CF_ARENA_SAVE+16)(R8), R5
	CMP  R3, R5
	BGE  rvi_str_clear_done
	MOVD CTX_ARENA_STR_SLAB(R19), R6
	LSL  $4, R5, R1
	ADD  R1, R6, R1
	LSL  $4, R3, R3
	ADD  R6, R3, R3

rvi_str_clear_loop:
	MOVD ZR, (R1)
	MOVD ZR, 8(R1)
	ADD  $16, R1, R1
	CMP  R3, R1
	BLT  rvi_str_clear_loop

rvi_str_clear_done:
	MOVD (CF_ARENA_SAVE+0)(R8), R1
	MOVD R1, CTX_ARENA_INT_IDX(R19)
	MOVD (CF_ARENA_SAVE+8)(R8), R1
	MOVD R1, CTX_ARENA_FLT_IDX(R19)
	MOVD (CF_ARENA_SAVE+16)(R8), R1
	MOVD R1, CTX_ARENA_STR_IDX(R19)
	MOVD (CF_ARENA_SAVE+32)(R8), R1
	MOVD R1, CTX_ARENA_BOOL_IDX(R19)
	MOVD (CF_ARENA_SAVE+40)(R8), R1
	MOVD R1, CTX_ARENA_UINT_IDX(R19)
	MOVD (CF_ARENA_SAVE+96)(R8), R1
	MOVD R1, CTX_ARENA_SLICEBYTE_IDX(R19)
	MOVD $1, R1
	MOVB R1, CTX_ARENA_BANKS_DIRTY(R19)

	MOVBU CF_HAS_GENERAL_ALLOC(R8), R3
	CBZ  R3, rvi_gen_clear_done
	MOVD $runtime·writeBarrier(SB), R3
	MOVBU (R3), R3
	CBNZ R3, rvi_gen_clear_slow
	MOVD CF_ARENA_SAVE_GENERAL_IDX(R8), R3
	MOVD CTX_ARENA_GEN_IDX(R19), R6
	SUB  R3, R6, R6
	CMP  $0, R6
	BLE  rvi_gen_clear_restore
	MOVD $24, R9
	MUL  R3, R9, R9
	MOVD CTX_ARENA_GENERAL_SLAB(R19), R7
	ADD  R9, R7, R7
rvi_gen_clear_zero:
	MOVD ZR, (R7)
	MOVD ZR, 8(R7)
	MOVD ZR, 16(R7)
	ADD  $24, R7, R7
	SUB  $1, R6, R6
	CBNZ R6, rvi_gen_clear_zero
rvi_gen_clear_restore:
	MOVD R3, CTX_ARENA_GEN_IDX(R19)
	MOVD $1, R6
	MOVB R6, CTX_ARENA_BANKS_DIRTY(R19)
	B    rvi_gen_clear_done
rvi_gen_clear_slow:
	BL   ·handlerCallInlineClearGeneralBank(SB)
	MOVD CTX_FRAME_POINTER(R19), R3
	SUB  $1, R3, R21
	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22
rvi_gen_clear_done:

	MOVD R21, CTX_FRAME_POINTER(R19)
	MOVD R22, CTX_CURRENT_FRAME(R19)

	MOVD CTX_ASM_CI_PTRS(R19), R1
	MOVD (R1)(R21<<3), R1
	MOVD R1, CTX_ASM_CALL_INFO_BASE(R19)

	MOVD CF_PROGRAM_COUNTER(R22), R20
	MOVD CF_REGS_INTS_PTR(R22), R23
	MOVD CF_REGS_FLOATS_PTR(R22), R24

	MOVD CF_REGS_STRINGS_PTR(R22), R1
	MOVD R1, CTX_STRINGS_BASE(R19)
	MOVD CF_REGS_UINTS_PTR(R22), R1
	MOVD R1, CTX_UINTS_BASE(R19)
	MOVD CF_REGS_BOOLS_PTR(R22), R1
	MOVD R1, CTX_BOOLS_BASE(R19)
	MOVD CF_REGS_GENERAL_PTR(R22), R1
	MOVD R1, CTX_GENERALS_BASE(R19)
	MOVD CF_REGS_SLICEBYTE_PTR(R22), R1
	MOVD R1, CTX_SLICES_BYTE_BASE(R19)
	MOVD CF_REGS_SLICESINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_INT_BASE(R19)
	MOVD CF_REGS_SLICESFLOAT_PTR(R22), R1
	MOVD R1, CTX_SLICES_FLOAT_BASE(R19)
	MOVD CF_REGS_SLICESSTRING_PTR(R22), R1
	MOVD R1, CTX_SLICES_STRING_BASE(R19)
	MOVD CF_REGS_SLICESBOOL_PTR(R22), R1
	MOVD R1, CTX_SLICES_BOOL_BASE(R19)
	MOVD CF_REGS_SLICESUINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_UINT_BASE(R19)
	MOVD CF_REGS_COMPLEX_PTR(R22), R1
	MOVD R1, CTX_COMPLEX_BASE(R19)

	MOVD CTX_DISPATCH_SAVES(R19), R1
	LSL  $DS_SIZE_SHIFT, R21, R7
	ADD  R1, R7, R1
	MOVD DS_CODE_BASE(R1), R22
	MOVD DS_CODE_LEN(R1), R21
	MOVD DS_INT_CONSTS(R1), R26
	MOVD DS_FLOAT_CONSTS(R1), R7
	MOVD R7, CTX_FLT_CONSTS_BASE(R19)
	MOVD DS_STRING_CONSTS(R1), R7
	MOVD R7, CTX_STR_CONSTS_BASE(R19)
	MOVD DS_BOOL_CONSTS(R1), R7
	MOVD R7, CTX_BOOL_CONSTS_BASE(R19)
	MOVD DS_UINT_CONSTS(R1), R7
	MOVD R7, CTX_UINT_CONSTS_BASE(R19)

	MOVD R22, CTX_CODE_BASE(R19)
	MOVD R21, CTX_CODE_LEN(R19)
	MOVD R20, CTX_PC(R19)
	MOVD R23, CTX_INTS_BASE(R19)
	MOVD R24, CTX_FLOATS_BASE(R19)
	MOVD R26, CTX_INT_CONSTS_BASE(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	DISPATCH_NEXT()

rvi_fallback:
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_RETURN_VOID, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	JMP  ·dispatchExit(SB)

// handlerTailCallInline handles OpTailCall in-loop via handlerTailCallInlineSubroutine (no exit-reason round-trip).
TEXT ·handlerTailCallInline(SB), NOSPLIT, $32-0
	NO_LOCAL_POINTERS
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	BL   ·handlerTailCallInlineSubroutine(SB)
	MOVD 0(RSP), R30
