	DISPATCH_NEXT()

// handlerTailCallInlineSubroutine performs the asmTailCallExecute round-trip and reloads dispatcher registers; CALLed from handlerTailCallInline.
TEXT ·handlerTailCallInlineSubroutine(SB), NOSPLIT, $24-0
	NO_LOCAL_POINTERS
	MOVD R19, 8(RSP)
	BL   ·asmTailCallExecute(SB)
	MOVD 16(RSP), R19
	MOVD CTX_PC(R19), R20
	MOVD CTX_CODE_BASE(R19), R22
	MOVD CTX_CODE_LEN(R19), R21
	MOVD CTX_INTS_BASE(R19), R23
	MOVD CTX_FLOATS_BASE(R19), R24
	MOVD CTX_INT_CONSTS_BASE(R19), R26
	MOVD CTX_JUMP_TABLE(R19), R25
	RET
